func scanIntoBookWithDistance(src interface{ Scan(dest ...any) error }, out *pb.Book, distance *float32) error {
	var idLocal int64
	var tenantLocal string
	var titleLocal string
	var authorIdLocal int64
	var scoreLocal sql.NullFloat64
	var pageCountLocal sql.NullInt32
	var summaryLocal sql.NullString
	var expiresAtLocal sql.NullTime
	var createdAtLocal sql.NullTime
	if err := src.Scan(&idLocal, &tenantLocal, &titleLocal, &authorIdLocal, &scoreLocal, &pageCountLocal, &summaryLocal, &expiresAtLocal, &createdAtLocal, distance); err != nil {
		return err
	}
	out.Id = idLocal
	out.Tenant = tenantLocal
	out.Title = titleLocal
	out.AuthorId = authorIdLocal
	out.Score = runtime.Float32PtrFromNull(scoreLocal)
	out.PageCount = runtime.Int32PtrFromNull(pageCountLocal)
	out.Summary = runtime.StringPtrFromNull(summaryLocal)
	if expiresAtLocal.Valid {
		out.ExpiresAt = runtime.TimeToProto(expiresAtLocal.Time)
	}
	if createdAtLocal.Valid {
		out.CreatedAt = runtime.TimeToProto(createdAtLocal.Time)
	}
	return nil
}

func bindForBookInsert(in *pb.Book) []any {
	return []any{
		in.GetId(),
		in.GetTenant(),
		in.GetTitle(),
		in.GetAuthorId(),
		runtime.NullableFloat32(in.Score),
		runtime.NullableInt32(in.PageCount),
		runtime.NullableString(in.Summary),
		runtime.ProtoToTimePtr(in.ExpiresAt),
		runtime.ProtoToTimePtr(in.CreatedAt),
	}
}

func bindForBookUpdate(in *pb.Book, pk ...any) []any {
	args := []any{
		in.GetTenant(),
		in.GetTitle(),
		in.GetAuthorId(),
		runtime.NullableFloat32(in.Score),
		runtime.NullableInt32(in.PageCount),
		runtime.NullableString(in.Summary),
		runtime.ProtoToTimePtr(in.ExpiresAt),
		runtime.ProtoToTimePtr(in.CreatedAt),
	}
	return append(args, pk...)
}


var _ pb.BookServiceServer = (*BookServer)(nil)
